KEYS ['version', 'tools']
COUNT 138
===== open_project
{
 "inputSchema": {
  "properties": {
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   },
   "path": {
    "type": "string",
    "description": "Absolute or ~ path to the file."
   }
  },
  "type": "object",
  "required": [
   "path"
  ]
 },
 "name": "open_project",
 "description": "Opens a project and shows its window. Takes a .framejob package, or any movie, sound file or picture — opening one of those builds a fresh UNTITLED project sized and rated to it with the file as the first clip on track 1, exactly as double-clicking it does. Answers already_open: true when that file is already open."
}
===== new_project
{
 "name": "new_project",
 "description": "Creates a blank 1920×1080 / 30 fps project and shows its window — File ▸ New Project. With path it is saved there straight away (a .framejob extension is added if missing) so later calls can name it; without one it stays an untitled draft until save_project. Change the size and rate afterwards with set_canvas. A path another open project holds is refused, and nothing is created; close_project closes that one first.",
 "inputSchema": {
  "type": "object",
  "properties": {
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   },
   "path": {
    "type": "string",
    "description": "Where to save the new project, e.g. ~/Movies/Cut.framejob."
   }
  },
  "required": []
 }
}
===== new_project_from_range
{
 "inputSchema": {
  "type": "object",
  "required": [
   "from",
   "to"
  ],
  "properties": {
   "to": {
    "type": "integer",
    "description": "Where the range ends on the TIMELINE, in ticks; must be after from."
   },
   "path": {
    "type": "string",
    "description": "Where to save the new project, an absolute path; .framejob is added when missing. Nothing may exist there yet. Without it the project opens untitled."
   },
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   },
   "from": {
    "description": "Where the range starts on the TIMELINE, in ticks (600000 per second).",
    "type": "integer"
   }
  }
 },
 "name": "new_project_from_range",
 "description": "Opens a NEW project holding exactly [from, to) of the top-level timeline, moved to start at 0 — what File ▸ New Project from Range… does with the In–Out range. Times are TIMELINE ticks (600000 per second), snapped to frames. A clip across an edge is cut there as split cuts it; a transition across an edge becomes a hard start or end; markers inside are kept; media no kept clip plays are left out. Each kept media's caches (filmstrips, waveforms, loudness, speech, sync, transcripts read on this Mac, the media analysis, reversed renders) and the graphic modules the kept clips draw, with every font and asset, are carried, so nothing is re-analysed; media files are never copied (the new project points at the same files), and a cloud transcript still owed a deletion stays behind. The project you name never changes and gets no undo step. Without path the new project opens untitled, with unsaved changes, named \"<name> (range)\"; with path it is saved there first. Refused while a nest is open, onto a path another open project holds or where anything already exists, and in the core's own sentence for a nest clip across an edge or a range where nothing plays. Answers {project, saved (with path), carried {files, bytes, seconds}}; name the new project by its path or name in later calls."
}
===== save_project
{
 "description": "Saves the project. A project that has never been saved — a new_project with no path, or a movie opened as one — needs a path; passing a path always writes there (Save As). Returns once the package is really on disk. A path another open project holds is refused; close_project closes that one first.",
 "inputSchema": {
  "type": "object",
  "properties": {
   "path": {
    "description": "Where to write the .framejob package. Required the first time; otherwise the project is written back to its own file.",
    "type": "string"
   },
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  },
  "required": []
 },
 "name": "save_project"
}
===== close_project
{
 "description": "Closes a project and its window — File ▸ Close (⌘W). A project with unsaved changes (get_project's unsaved_changes) is refused unless discard is true, and so is a window with a sheet open; nothing is written, so save_project first to keep the changes. A later call naming the closed project's path is refused. open_project closes nothing.",
 "inputSchema": {
  "type": "object",
  "properties": {
   "discard": {
    "type": "boolean",
    "description": "Close even with unsaved changes, losing them. Default false."
   },
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  },
  "required": []
 },
 "name": "close_project"
}
===== get_project
{
 "description": "The whole project as JSON: canvas (width, height, fps [num, den], background, fit_new_clips, timecode_frames), media, tracks, clips and markers, with next_id — the schema every op edits. Plus the state that is deliberately NOT in the model and lives only in the app: playhead, selection and the in/out range. Read this first: every other tool names things by the ids it reports, and clip, track, marker and media ids share ONE number space, so an id is unambiguous on its own. tracks[0] is the BACK of the layer stack (the bottom lane of the timeline); times are ticks at 600000 per second. missing_media lists media whose file has moved — relink_media points it at the new one. graphics: every module in the package's graphics/ with its revision, whether it compiles, and the clips drawn by it.",
 "name": "get_project",
 "inputSchema": {
  "type": "object",
  "required": [],
  "properties": {
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  }
 }
}
===== undo
{
 "description": "Undoes one step — Edit ▸ Undo (⌘Z). Every tool that edits the project makes exactly one step, so one undo walks back exactly one call. Reports the name of the step it undid. View-state tools (set_playhead, set_range) make no step. Errors when there is nothing to undo.",
 "name": "undo",
 "inputSchema": {
  "properties": {
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  },
  "required": [],
  "type": "object"
 }
}
===== redo
{
 "inputSchema": {
  "type": "object",
  "properties": {
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  },
  "required": []
 },
 "name": "redo",
 "description": "Redoes one undone step — Edit ▸ Redo (⇧⌘Z). Any new edit clears the redo stack, exactly as in the app."
}
===== set_playhead
{
 "name": "set_playhead",
 "description": "Moves the playhead and seeks the preview. View state, not an edit: nothing is undoable and the project is untouched. split, freeze_frame and add_marker default to this time.",
 "inputSchema": {
  "properties": {
   "t": {
    "description": "Time in TICKS — 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000. Rounded to the project's frame grid.",
    "type": "integer"
   },
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  },
  "required": [
   "t"
  ],
  "type": "object"
 }
}
===== set_range
{
 "inputSchema": {
  "type": "object",
  "properties": {
   "start": {
    "description": "In point, in TICKS — 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000. Rounded to the project's frame grid.",
    "type": "integer"
   },
   "end": {
    "description": "Out point, in TICKS — 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000. Rounded to the project's frame grid.",
    "type": "integer"
   },
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  },
  "required": []
 },
 "description": "Sets the in/out range — Mark ▸ Set In (I) and Set Out (O). View state, not an edit: nothing is undoable and the project is untouched. Call it with NO bounds to clear the range (⌥X). export {range: \"in_out\"} writes only this span; get_project reports it as in_out_range.",
 "name": "set_range"
}
===== set_selection
{
 "name": "set_selection",
 "description": "Selects clips — clicking one in the timeline or on the canvas, and Edit ▸ Select All (⌘A). View state like the playhead and the range: nothing is undoable and the project is untouched. It matters because the canvas handles, crop mode and every inspector pane act on the SELECTION, so this is how you put the app into the state a screenshot should show. Call it with no clips (or []) to select nothing; get_project reports the result as selection. Note that the ops themselves take their own clips argument — selecting is not a prerequisite for editing.",
 "inputSchema": {
  "required": [],
  "type": "object",
  "properties": {
   "clips": {
    "type": "array",
    "items": {
     "type": "integer"
    },
    "description": "Clip ids to select (get_project lists them). Omit or pass an empty array to select nothing."
   },
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  }
 }
}
===== set_scope
{
 "name": "set_scope",
 "inputSchema": {
  "required": [],
  "type": "object",
  "properties": {
   "nest": {
    "type": "integer",
    "description": "The nest to open, by id (get_project lists them under nests). It has to be shown by a clip on the TIMELINE: this is the view, and the app cannot show its way into a nest the timeline does not reach — an op's own scope still can. Where two clips show one nest the earliest is entered, ties going to the lower id."
   },
   "clip": {
    "type": "integer",
    "description": "The nest CLIP to open — the precise spelling, and what a double-click sends: it names the nest and the start the times inside are measured from, which two clips showing one nest do not share. A clip that shows no nest is refused by name. Pass this or nest, not both."
   },
   "project": {
    "type": "string",
    "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."
   }
  }
 },
 "description": "Opens a nest so the app is LOOKING INSIDE it — double-clicking a nest clip in the timeline (Clip ▸ Open Nest, ⌘↓; Close Nest, ⌘↑). View state like the playhead and the selection: no op runs, nothing is undoable and the project is untouched. What it changes is what the app shows and therefore what get_project and render_frame answer — while a nest is open those report and draw that nest's own tracks, clips and frozen canvas rather than the timeline's, which is the only way to SEE what an edit inside one did. Name the nest, or the clip that shows it; call it with neither to come back out. While a nest is open every op you send lands INSIDE it unless the op's own scope argument says otherwise, exactly as an edit made by hand goes where the window is looking — so this is the setting to change first and the one to clear when you are done. Editing inside a nest does not require it: an op carrying scope works from wherever you are."
}

