256	    /// `close_project` — File ▸ Close (⌘W; spec §11 #40). It runs on main,
257	    /// as the menu item does, and closes through `ProjectDocument.close()`,
258	    /// which releases the recipe key and the graphic store; it never writes
259	    /// the package. A window with a sheet attached is refused first, because
260	    /// the sheet is window-modal work in progress (`handleEditorKey`'s rule);
261	    /// then unsaved changes, unless `discard: true`. Under autosave in place
262	    /// "unsaved" means "not yet autosaved", and that is all `discard` loses.
263	    func closeProject(_ a: [String: Any]) throws -> String {
264	        let discard = try boolArg(a, "discard") ?? false
265	        let document = try target(a)
266	        let name = document.displayName ?? "Untitled"
267	        let path = Self.path(of: document)
268	        let edited = document.isDocumentEdited
269	        if document.windowControllers.contains(where: { $0.window?.attachedSheet != nil }) {
270	            throw ToolError(
271	                message: "\(name) has a sheet open on its window, so close_project left it "
272	                    + "open: finish or cancel the sheet first.")
273	        }
274	        if edited && !discard {
275	            throw ToolError(
276	                message: "\(name) has unsaved changes, so close_project left it open: "
277	                    + "save_project saves them, or close_project with discard: true closes "
278	                    + "it and loses them.")
279	        }
280	        document.close()
281	        return try jsonResult(
282	            [
283	                "ok": true, "closed": name, "path": path ?? NSNull(),
284	                "discarded_changes": edited,
285	            ])
286	    }
