339	    // MARK: - Transport
340	
341	    /// `set_playhead` — clicking the ruler / the transport keys. View state,
342	    /// not an edit: no op runs and no undo step is registered (spec §5.2). It
343	    /// goes through `EditorViewController.setPlayhead` when the project has a
344	    /// window, so the player seeks and every pane follows; a windowless
345	    /// document just gets the time, which is all `render_frame` needs.
346	    func setPlayhead(_ a: [String: Any]) throws -> String {
347	        let document = try target(a)
348	        let time = try timeArg(a, "t", document)
349	        let clamped = max(0, time)
350	        if let editor = editor(document) {
351	            editor.setPlayhead(clamped)
352	            editor.viewStateDidChange()
353	        } else {
354	            document.playhead = clamped
355	        }
356	        return try jsonResult(
357	            ["ok": true, "playhead": document.playhead, "project": summary(document)])
358	    }
359	
360	    /// `set_range` — Mark ▸ Set In / Set Out / Clear Range (I, O, ⌥X:
361	    /// `EditorViewController.setInPoint` / `setOutPoint` /
362	    /// `clearInOutRange`). View state like the playhead, so no op runs and
363	    /// nothing is undoable — but `export {range: "in_out"}` reads it, and
364	    /// `get_project` already reported it, so this is the write half of a
365	    /// field the agent could previously only look at.
366	    ///
367	    /// With neither bound the range is CLEARED, which is what ⌥X does.
368	    func setRange(_ a: [String: Any]) throws -> String {
369	        let document = try target(a)
370	        let start = try optionalTimeArg(a, "start", document)
371	        let end = try optionalTimeArg(a, "end", document)
372	        if start == nil && end == nil {
373	            document.inOutRange = nil
374	        } else {
375	            let from = max(0, start ?? document.inOutRange?.start ?? 0)
376	            let to = max(0, end ?? document.inOutRange?.end ?? document.project.duration)
377	            guard to > from else {
378	                throw ToolError(
379	                    message: "The range end (\(to)) must be after its start (\(from)); "
380	                        + "call set_range with no arguments to clear it.")
381	            }
382	            document.inOutRange = (start: from, end: to)
383	        }
384	        if let editor = editor(document) {
385	            editor.viewStateDidChange()
386	            editor.applyLoopRange()
387	        }
388	        var result: [String: Any] = ["ok": true, "project": summary(document)]
389	        if let range = document.inOutRange {
390	            result["in_out_range"] = ["start": range.start, "end": range.end]
391	        } else {
392	            result["in_out_range"] = NSNull()
393	        }
394	        return try jsonResult(result)
395	    }
396	
397	    /// `set_selection` — clicking a clip in the timeline
398	    /// (`EditorViewController+Timeline.timelineSelected`) or on the canvas
399	    /// (`+Canvas.canvasSelected`), and Edit ▸ Select All / Select Forward
400	    /// (`selectAll(_:)`, `selectAfterPlayhead(_:)`). View state like the
401	    /// playhead and the range: no op runs and nothing is undoable.
402	    ///
403	    /// It is the write half of a field `get_project` already reported, and
404	    /// the one the agent was missing: the canvas handles, crop mode and
405	    /// every inspector pane act on the SELECTION, so without this nothing
406	    /// they do could be driven or checked by driving the app — which is why
407	    /// spec §10 step 8 stayed unverified.
408	    ///
409	    /// **Its ids mean the OPEN container** (road map 2's phase 9), and it
410	    /// gets that from `clipsArg` without a line of its own: a selection is
411	    /// clip ids in whichever container the app is looking at
412	    /// (`ProjectDocument.setNestPath` moves the two together), so with a nest
413	    /// open this selects inside it and cannot name a clip on the timeline.
414	    /// That is the same rule `effectiveScope` gives every other tool, read
415	    /// for a tool that has no `scope` argument of its own to override it
416	    /// with — the way in is `set_scope`, which is where a view is chosen.
417	    func setSelection(_ a: [String: Any]) throws -> String {
418	        let document = try target(a)
419	        var ids: [UInt32] = []
420	        if let raw = a["clips"], !(raw is NSNull) {
421	            // An explicit `[]` means "select nothing", which is a real
422	            // intent here — unlike an OP over no clips, the mistake
423	            // `optionalClipsArg` refuses an empty list as. Omitting `clips`
424	            // does the same, the way `set_range` with no bounds clears the
425	            // range.
426	            if let array = raw as? [Any], array.isEmpty {
427	                ids = []
428	            } else {
429	                ids = try clipsArg(a, "clips", document)
430	            }
431	        }
432	        // `clipsArg` validating every id against the snapshot is the ONLY
433	        // thing keeping a dead id out of the selection: `viewStateDidChange`
434	        // republishes the view state but does not run
435	        // `ProjectDocument.clampViewState`, which prunes on a MODEL change,
436	        // so nothing downstream will notice one.
437	        document.selection = Set(ids)
438	        if let editor = editor(document) {
439	            editor.viewStateDidChange()
440	        }
441	        return try jsonResult(
442	            [
443	                "ok": true,
444	                "selection": document.selection.sorted().map { Int($0) },
445	                "project": summary(document),
446	            ])
447	    }
448	}
