133	            Self.destinationURL($0, extension: ProjectDocument.projectFileExtension)
134	        }
135	        let document = try onMain { () throws -> ProjectDocument in
136	            if let url { try self.refuseHeldPath(url, except: nil, tool: "new_project") }
