190	    /// The open document whose file is `url` — the path `get_project` reports
191	    /// for it, `fileURL` or the movie it was built from — compared exactly and
192	    /// canonically, as `target(_:)` compares: two spellings of one file that
193	    /// failed to match would put two documents at one path. `except` is
194	    /// skipped (`===`), for a save that is that document's own. Main only.
195	    func documentHolding(_ url: URL, except: ProjectDocument?) -> ProjectDocument? {
196	        let canonical = Self.canonical(url.path)
197	        return openProjects().first { document in
198	            if let except, document === except { return false }
199	            guard let open = Self.path(of: document) else { return false }
200	            return open == url.path || Self.canonical(open) == canonical
201	        }
202	    }
