204	    /// Refuses a write to a path another open document holds (spec §11 #40),
205	    /// naming that document and the way out, and then to a path a person's
206	    /// open is still reading (spec §11 #234). Main only, so `save_project`
207	    /// and `new_project` call it inside `onMain`. The save is a later hop:
208	    /// an open that begins after this check is not seen (#234's risks).
209	    func refuseHeldPath(_ url: URL, except: ProjectDocument?, tool: String) throws {
210	        if let holder = documentHolding(url, except: except) {
211	            throw ToolError(
212	                message: "Another open project (\(holder.displayName ?? "Untitled")) is at "
213	                    + "\(url.path), so \(tool) did not write there: close_project closes it, "
214	                    + "or pass another path.")
215	        }
216	        guard ProjectDocumentController.isOpening(url) else { return }
217	        throw ToolError(
218	            message: "\(url.path) is being opened in a window, so \(tool) did not write "
219	                + "there: call \(tool) again once it has opened, or pass another path.")
220	    }
221	
222	    /// Writes `document` and WAITS for NSDocument's asynchronous save to
223	    /// finish, so the tool's answer is only sent once the package is really on
224	    /// disk and the agent can read it back.
225	    ///
226	    /// The wait is why `save_project` and `new_project` run on the server
227	    /// thread: `save(to:ofType:for:completionHandler:)` delivers its
228	    /// completion on the MAIN thread, which a main-thread wait would be
229	    /// occupying.
230	    func save(
231	        _ document: ProjectDocument, to url: URL, operation: NSDocument.SaveOperationType
232	    ) throws {
233	        guard !Thread.isMainThread else {
234	            throw ToolError(message: "Saving cannot run on the main thread.")
235	        }
236	        let semaphore = DispatchSemaphore(value: 0)
237	        let box = AgentBox<(any Error)?>()
238	        onMain {
239	            document.save(
240	                to: url, ofType: ProjectDocument.projectTypeIdentifier, for: operation
241	            ) { error in
242	                box.value = error
243	                semaphore.signal()
244	            }
245	        }
246	        guard semaphore.wait(timeout: .now() + 120) == .success else {
247	            throw ToolError(message: "Timed out saving \(url.lastPathComponent).")
248	        }
249	        if let error = box.value ?? nil {
250	            throw ToolError(message: error.localizedDescription)
251	        }
252	    }
