137	    /// quotes the string as the caller sent it.
138	    func enumArg<T: RawRepresentable & CaseIterable>(
139	        _ a: [String: Any], _ key: String, _ type: T.Type,
140	        label: String? = nil, folding: Bool = false
141	    ) throws -> T? where T.RawValue == String {
142	        guard let raw = try stringArg(a, key) else { return nil }
