154	    private static func enumCase<T: RawRepresentable & CaseIterable>(
155	        _ raw: String, _ type: T.Type, label: String, folding: Bool
156	    ) throws -> T where T.RawValue == String {
157	        guard let value = T(rawValue: folding ? raw.lowercased() : raw) else {
158	            let words = T.allCases.map(\.rawValue).joined(separator: ", ")
159	            throw ToolError(message: "\(label) must be one of \(words) (got \"\(raw)\").")
160	        }
