impl Project {
    /// Sets or clears a video media's camera-log setting (spec §11 GR-16)
    /// and a PQ file's peak override (HD-12). `Err` for an unknown media or
    /// an unreadable `color`; a refusal, in the rule's own sentence, for
    /// `detected`, `pq`, a `peak` out of range or on a file that is not PQ,
    /// an asked `color` with none of `log`, `lut` and `peak`, or a setting
    /// [`Project::check_media_color`] refuses.
    pub(crate) fn set_media_color(&self, media: u32, color: &Value) -> Result<Outcome, String> {
        let current = self.require_media(media)?.color;
        // Import's reading, kept by every op: `pq` without the override.
        let reading = current
            .and_then(|c| c.pq)
            .map(|pq| PqColor { peak: None, ..pq });
        let stored = match read_color(color)? {
            None => reading.map(|pq| MediaColor {
                pq: Some(pq),
                ..MediaColor::default()
            }),
            Some(asked) => match self.asked_color(media, asked, reading) {
                Ok(setting) => Some(setting),
                Err(why) => return Ok(Outcome::Refused(why)),
            },
        };
        let mut next = self.clone();
        let Some(row) = next.media.iter_mut().find(|m| m.id == media) else {
            return Err(format!("no media with id {media}"));
        };
        row.color = stored;
        if stored.is_some() {
            if let Err(why) = self.check_media_color(row) {
                return Ok(Outcome::Refused(why));
            }
        }
        self.finish(next)
    }

    /// The setting an asked `color` stores on `media` beside its `reading`,
    /// or (`Err`) the refusal in the rule's own sentence, in this order: `detected`,
    /// `pq`, a `peak` outside [`PEAK_MIN`]–[`PEAK_MAX`] or on media that is
    /// not a PQ file, the media's kind (an image passes only with a `peak`
    /// alone, spec §11 HD-20 (b)), and none of `log`, `lut` and `peak`.
    fn asked_color(
        &self,
        media: u32,
        asked: Asked,
        reading: Option<PqColor>,
    ) -> Result<MediaColor, String> {
        let given = asked.color;
        if given.detected {
            return Err("color.detected is written by import, not set".to_string());
        }
        if given.pq.is_some() {
            return Err("color.pq is read from the file at import, not set".to_string());
        }
        let peak = match asked.peak {
            None => None,
            Some(n) => match u32::try_from(n) {
                Ok(n) if (PEAK_MIN..=PEAK_MAX).contains(&n) => Some(n),
                _ => {
                    return Err(format!(
                        "color.peak must be {PEAK_MIN}–{PEAK_MAX} cd/m², not {n}"
                    ))
                }
            },
        };
        if peak.is_some() && reading.is_none() {
            return Err(format!(
                "media {media} is not a PQ file; only a PQ file takes a peak"
            ));
        }
        if let Some(row) = self.media(media) {
            let image_ok = peak.is_some()
                && given.log.is_none()
                && given.lut.is_none()
                && given.gamut.is_none();
            check_kind(row, image_ok)?;
        }
        if given.log.is_none() && given.lut.is_none() && peak.is_none() {
            return Err(NEEDS_LOG_OR_LUT.to_string());
        }
        let mut setting = given;
        if let (Some(log), None) = (setting.log, setting.gamut) {
            setting.gamut = log.gamuts().first().copied();
        }
        setting.pq = reading.map(|pq| PqColor { peak, ..pq });
        Ok(setting)
    }

    /// A media's `color` against this project; `Ok` for a media without one.
    /// Each sentence is the rule's own, in this order: the media's kind (an
    /// image passes only with an import's `pq` alone, spec §11 HD-20 (b)), a
    /// setting with neither or both of `log` and `lut` (neither is a PQ
    /// file's `pq` alone, which passes), a `gamut` without a `log`, a pairing
    /// the curve does not take, a `lut` that is not a `lut` media of the
    /// project, and `pq`'s own ([`check_pq`]).
    pub(crate) fn check_media_color(&self, media: &Media) -> Result<(), String> {
        let Some(color) = media.color else {
            return Ok(());
        };
        let image_ok = color.pq.is_some()
            && !color.detected
            && color.log.is_none()
            && color.lut.is_none()
            && color.gamut.is_none();
        check_kind(media, image_ok)?;
        match (color.log, color.lut) {
            (None, None) if color.pq.is_none() || color.detected => {
                return Err(NEEDS_LOG_OR_LUT.to_string())
            }
            (Some(_), Some(_)) => return Err("color takes log or lut, not both".to_string()),
            _ => {}
        }
        if let (None, Some(_)) = (color.log, color.gamut) {
            return Err("color.gamut goes with log".to_string());
        }
        if let (Some(log), Some(gamut)) = (color.log, color.gamut) {
            if !log.gamuts().contains(&gamut) {
                let takes: Vec<String> = log.gamuts().iter().map(|g| spelled(*g)).collect();
                return Err(format!(
                    "{} takes gamut {}, not {}",
                    spelled(log),
                    takes.join(" or "),
                    spelled(gamut)
                ));
            }
        }
        if let Some(id) = color.lut {
            self.check_lut_reference("color.lut", id)?;
        }
        color.pq.map_or(Ok(()), check_pq)
    }

    /// What step 0 converts `media` with, as the recipe layer's and the plan
    /// segment's `input`: `{log, gamut}` for a built-in curve (the gamut its
    /// first when the stored one is absent), `{lut}` naming a `lut` media of
    /// the project, and `peak` — a PQ file's effective peak (spec §11 HD-12)
    /// — beside either or alone; or `null` — no setting, no such media, or a
    /// `lut` that names none and no peak. A PQ file whose import read nothing
    /// publishes nothing new, so its plan and recipe are the text they were.
    pub(crate) fn media_input(&self, media: u32) -> Value {
        let Some(color) = self.media(media).and_then(|m| m.color) else {
            return Value::Null;
        };
        let mut out = Map::new();
        if let Some(log) = color.log {
            let Some(gamut) = color.gamut.or_else(|| log.gamuts().first().copied()) else {
                return Value::Null;
            };
            out.insert("log".to_string(), Value::from(spelled(log)));
            out.insert("gamut".to_string(), Value::from(spelled(gamut)));
        } else if let Some(id) = color.lut {
            if self.media(id).is_some_and(|m| m.kind == MediaKind::Lut) {
                out.insert("lut".to_string(), Value::from(id));
            }
        }
        if let Some(peak) = color.pq.and_then(|pq| pq.effective()) {
            out.insert("peak".to_string(), Value::from(peak));
        }
        if out.is_empty() {
            Value::Null
        } else {
            Value::Object(out)
        }
    }

    /// The media whose `color.lut` is `lut`, in list order.
    pub(crate) fn media_converted_by(&self, lut: u32) -> Vec<u32> {
        self.media
            .iter()
            .filter(|m| m.color.and_then(|color| color.lut) == Some(lut))
            .map(|m| m.id)
            .collect()
    }
}
//! Speech spans on a media (format 29, spec §11 AU-110, AU-111):
//! `set_media_speech`, and the rules a `media.speech` obeys, written once for
//! the op and for `validate`.
//!
//! - **The op.** `set_media_speech {media, spans}` stores the spans the app
//!   read from its voice-activity cache on the media, as forward-file SOURCE
//!   ticks `[start, end)`. Choosing Duck by Speech writes it, in the same
//!   undo step as the `set_audio` that turns the mode on, for a media that
//!   has none yet; an empty list is a media in which no speech was found,
//!   and is stored as such. Equal spans are an identity. Unknown media is an
//!   `Err`; every rule below is a refusal in its own sentence.
//! - **The rules** ([`Project::check_media_speech`]): the media has audio;
//!   each span starts at 0 or later, ends after it starts and at or before
//!   the media's `duration`; the spans are sorted and do not overlap (they
//!   may touch); there are at most [`MAX_SPEECH_SPANS`]. `validate` holds a
//!   file to the same rules, as errors.
//! - **What reads them** is `audio_duck_speech.rs`, for a ducker in `speech`
//!   mode. A relink that probes the new file clips or clears them
//!   (`edit_relink.rs`, AU-116); `add_media` and a probe never carry them.

use crate::model::{Media, Project};
use crate::outcome::Outcome;
use crate::time::Ticks;

/// The most spans one media may carry: some 28 hours of speech broken every
/// second, and a bound on what one op can make the plan sample.
pub const MAX_SPEECH_SPANS: usize = 100_000;

impl Project {
    /// Stores `spans` as `media`'s speech (spec §11 AU-110). `Err` for an
    /// unknown media; a refusal for spans [`Project::check_media_speech`]
    /// refuses; an identity when they equal what the media already has.
    pub fn set_media_speech(&self, media: u32, spans: &[[Ticks; 2]]) -> Result<Outcome, String> {
        let current = self.require_media(media)?;
        if current.speech.as_deref() == Some(spans) {
            return Ok(Outcome::Identity);
        }
        let mut next = self.clone();
        let Some(row) = next.media.iter_mut().find(|m| m.id == media) else {
            return Err(format!("no media with id {media}"));
        };
        row.speech = Some(spans.to_vec());
        if let Err(why) = self.check_media_speech(row) {
            return Ok(Outcome::Refused(why));
        }
        self.finish(next)
    }

    /// The rules a media's `speech` obeys, each failure its own sentence
    /// naming the media and the span. A media without `speech` passes.
    pub(crate) fn check_media_speech(&self, media: &Media) -> Result<(), String> {
        let Some(spans) = &media.speech else {
            return Ok(());
        };
        let id = media.id;
        if !media.has_audio {
            return Err(format!(
                "media {id} has no audio, so it has no speech to duck by"
            ));
        }
        if spans.len() > MAX_SPEECH_SPANS {
            return Err(format!(
                "media {id} carries {} speech spans, more than {MAX_SPEECH_SPANS}",
                spans.len()
            ));
        }
        let mut previous: Option<Ticks> = None;
        for (i, &[start, end]) in spans.iter().enumerate() {
            if start < 0 {
                return Err(format!(
                    "media {id} speech span {i} starts at {start}, before 0"
                ));
            }
            if end <= start {
                return Err(format!(
                    "media {id} speech span {i} ends at {end}, not after its start {start}"
                ));
            }
            if end > media.duration {
                return Err(format!(
                    "media {id} speech span {i} ends at {end}, past the media's duration {}",
                    media.duration
                ));
            }
            if let Some(before) = previous.filter(|before| start < *before) {
                return Err(format!(
                    "media {id} speech span {i} starts at {start}, before span {} ends at \
                     {before}: speech spans are sorted and do not overlap",
                    i - 1
                ));
            }
            previous = Some(end);
        }
        Ok(())
    }
}
//! `keep_range` — the project as one range of its own timeline (road map
//! "creator-jobs" CJ5a, spec §11 CJ-50).
//!
//! The answer holds only `[from, to)` of the TOP-LEVEL timeline, moved to
//! start at 0: what a derived document (File ▸ New Project from Range…,
//! `new_project_from_range`, CJ5b) is made of. It is applied only to that
//! document's handle, never to the one a person is editing, which is why it
//! ignores locks — the derived document keeps them — and why it has no tool
//! of its own (`AgentServer.opsWithoutTools`).
//!
//! In order, each a part of CJ-50:
//!
//! - (a) Both bounds are snapped and clamped to 0, as every op's ticks are;
//!   `to` not after `from` is an `Err`, not an identity and not a reorder
//!   (`edit_time.rs`'s `ordered_range` is deliberately not followed).
//! - (b) A nest clip a bound lies strictly inside is refused: a nest clip
//!   has no in point, so a cut there would replay it from its start.
//! - (c) Every clip, on every track, that a bound lies strictly inside is
//!   cut there by `split`'s own cutter (`edit_split.rs`'s `split_clip`) and
//!   its halves paired (`edit_link.rs`'s `pair_split_halves`), so a ramp, a
//!   timed caption page and a linked pair follow `split`'s rules exactly.
//! - (d) THE overlap rule at the edges, judged on the SOURCE's overlaps: an
//!   edge inside a transition drops the piece beyond it — the outgoing
//!   clip's piece starting at `from`, the incoming clip's piece ending at
//!   `to` — and the incoming piece that starts at `from` loses its
//!   `transition_in` (a hard start). When both bounds lie in one overlap,
//!   the incoming piece the `from` rule kept is not dropped again at `to`.
//! - (e) Clips not wholly inside the range go, the rest move by −`from`;
//!   markers inside are kept and moved, the others go; tracks and canvas
//!   are untouched.
//! - (f) Nests no kept clip reaches, and media no kept clip plays, names in
//!   a look, or converts through as `color.lut`, go.
//! - (g) Nothing left to play is refused, and so is a transition wholly
//!   inside the range whose clip an edge cut too short for it: the edge
//!   rule repairs only an overlap an edge lies in, and clips never push
//!   each other.
//!
//! The exit is `finish`, whose `settle_links` clears a link a dropped or
//! removed piece left one-sided.

use std::collections::{HashMap, HashSet};

use crate::edit_clip::clip_end;
use crate::edit_link::pair_split_halves;
use crate::edit_split::split_clip;
use crate::lut::look_media_ids;
use crate::model::{Clip, Project, Source};
use crate::outcome::Outcome;
use crate::time::Ticks;
use crate::transition::overlap_limit;

/// The nest a clip shows, when it is a nest clip.
fn nest_of(clip: &Clip) -> Option<u32> {
    match clip.source {
        Source::Nest { project } => Some(project),
        _ => None,
    }
}

/// Every piece's SOURCE clip: a second half maps to the clip its original
/// was cut from, so a piece cut twice still names the clip a person saw.
/// An uncut clip, absent from the map, is its own source.
struct Pieces(HashMap<u32, u32>);

impl Pieces {
    fn source(&self, piece: u32) -> u32 {
        self.0.get(&piece).copied().unwrap_or(piece)
    }

    /// The pieces of `source` in `project` satisfying `which`.
    fn of(&self, project: &Project, source: u32, which: impl Fn(&Clip) -> bool) -> Vec<u32> {
        project
            .clips
            .iter()
            .filter(|c| self.source(c.id) == source && which(c))
            .map(|c| c.id)
            .collect()
    }
}

impl Project {
    /// The project holding only `[from, to)` of its top-level timeline,
    /// moved to start at 0 (spec §11 CJ-50; the module doc is the rule).
    pub fn keep_range(&self, from: Ticks, to: Ticks) -> Result<Outcome, String> {
        let from = self.snapped(from).max(0);
        let to = self.snapped(to).max(0);
        if to <= from {
            return Err(format!(
                "keep_range's to must be after its from (from {from}, to {to} ticks, on the frame \
                 grid)"
            ));
        }

        // (b) Before anything is cut: a nest clip across either edge.
        for bound in [from, to] {
            if let Some(nest) = self
                .clips
                .iter()
                .find(|c| nest_of(c).is_some() && c.start < bound && bound < clip_end(c))
            {
                return Ok(Outcome::Refused(format!(
                    "Clip {} is a nest across the range's edge; a nest clip has no in point, so a \
                     cut there would replay it from its start. Move the edge, or open the nest \
                     and unnest it.",
                    nest.id
                )));
            }
        }

        // (c) Both bounds cut on every track, locked or not.
        let mut next = self.clone();
        let mut pieces = Pieces(HashMap::new());
        for bound in [from, to] {
            let ids: Vec<u32> = next
                .clips
                .iter()
                .filter(|c| c.start < bound && bound < clip_end(c))
                .map(|c| c.id)
                .collect();
            let mut halves: Vec<(u32, u32)> = Vec::new();
            for id in ids {
                // `split_clip` allocates the second half's id first.
                let second = next.next_id;
                if split_clip(&mut next, id, bound) {
                    let source = pieces.source(id);
                    pieces.0.insert(second, source);
                    halves.push((id, second));
                }
            }
            pair_split_halves(&mut next, &halves);
        }

        // (d) THE overlap rule at the edges, on the source's overlaps.
        let mut dropped: HashSet<u32> = HashSet::new();
        let mut hard_start: HashSet<u32> = HashSet::new();
        for track in &self.tracks {
            for overlap in self.overlaps_on_track(track.id) {
                let os = overlap.start;
                let oe = overlap.start.saturating_add(overlap.duration);
                if os <= from && from < oe {
                    dropped.extend(pieces.of(&next, overlap.earlier, |c| c.start == from));
                    hard_start.extend(pieces.of(&next, overlap.later, |c| c.start == from));
                }
                if os < to && to <= oe {
                    // A piece starting at `from` is the incoming piece the
                    // `from` rule just kept: both bounds lie in this one
                    // overlap, and it stays, hard-cut.
                    dropped.extend(pieces.of(&next, overlap.later, |c| {
                        clip_end(c) == to && c.start != from
                    }));
                }
            }
        }

        // (e) Keep what lies wholly inside, and move it to 0.
        next.clips
            .retain(|c| !dropped.contains(&c.id) && c.start >= from && clip_end(c) <= to);
        for clip in &mut next.clips {
            clip.start = clip.start.saturating_sub(from);
            if hard_start.contains(&clip.id) {
                clip.transition_in = None;
            }
        }
        next.markers.retain(|m| from <= m.time && m.time < to);
        for marker in &mut next.markers {
            marker.time = marker.time.saturating_sub(from);
        }

        // (f) What the kept timeline no longer reaches.
        prune_unused(&mut next);

        // (g) Refusals on what is left.
        if next.clips.is_empty() {
            return Ok(Outcome::Refused(format!(
                "Nothing plays between {from} and {to} ticks."
            )));
        }
        for track in &next.tracks {
            let Err(why) = next.check_overlap_rule(&[], track.id, &[]) else {
                continue;
            };
            let too_long = next.overlaps_on_track(track.id).into_iter().find(|o| {
                match (next.clip(o.earlier), next.clip(o.later)) {
                    (Some(a), Some(b)) => o.duration > overlap_limit(a, b),
                    _ => false,
                }
            });
            let Some(overlap) = too_long else {
                return Ok(Outcome::Refused(why));
            };
            let limit = match (next.clip(overlap.earlier), next.clip(overlap.later)) {
                (Some(a), Some(b)) => overlap_limit(a, b),
                _ => 0,
            };
            return Ok(Outcome::Refused(format!(
                "Keeping {from} to {to} ticks would leave clips {} and {} overlapping by {} \
                 ticks, more than half of the shorter piece ({limit} ticks); move an edge \
                 further from their transition.",
                pieces.source(overlap.earlier),
                pieces.source(overlap.later),
                overlap.duration
            )));
        }
        self.finish(next)
    }
}

/// Removes the nests no kept top-level clip reaches (through nest clips in
/// kept nests too), and every media that no kept clip plays or names in a
/// look and no kept media names as its `color.lut`. Order is kept.
fn prune_unused(project: &mut Project) {
    let mut nests: HashSet<u32> = HashSet::new();
    let mut frontier: Vec<u32> = project.clips.iter().filter_map(nest_of).collect();
    while let Some(id) = frontier.pop() {
        if !nests.insert(id) {
            continue;
        }
        if let Some(nest) = project.nest(id) {
            frontier.extend(nest.clips.iter().filter_map(nest_of));
        }
    }
    project.nests.retain(|n| nests.contains(&n.id));

    let mut media: HashSet<u32> = HashSet::new();
    let clips = project
        .clips
        .iter()
        .chain(project.nests.iter().flat_map(|n| n.clips.iter()));
    for clip in clips {
        media.extend(clip.source.media());
        media.extend(look_media_ids(clip));
        media.extend(crate::video_gate::hide_silent_media(clip));
    }
    // A kept media's LUT, and that LUT's, until nothing new is named.
    loop {
        let luts: Vec<u32> = project
            .media
            .iter()
            .filter(|m| media.contains(&m.id))
            .filter_map(|m| m.color.as_ref().and_then(|c| c.lut))
            .filter(|id| !media.contains(id))
            .collect();
        if luts.is_empty() {
            break;
        }
        media.extend(luts);
    }
    project.media.retain(|m| media.contains(&m.id));
}
