159	    /// Shifts `clips` by `delta` ticks and, when `track` is given, moves
160	    /// them to that track keeping their relative track offsets (spec §6).
161	    ///
162	    /// The EARLIEST clip clamps at 0 and the rest keep their offsets, so a
163	    /// drag past the start of the timeline compresses nothing. The
164	    /// destination is computed as an index delta from the first clip of the
165	    /// selection (by track order, then start), which is what makes a
166	    /// two-track selection land two tracks apart.
167	    ///
168	    /// Refuses when a clip would land outside the track list or the overlap
169	    /// rule fails on any affected track. A clip that gains a predecessor
170	    /// overlap and has no transition gets a cross dissolve.
171	    ///
172	    /// **A linked partner follows in TIME, not in track** (spec §11 AU-91):
173	    /// every clip of the closure moves by the one delta, the clamp at 0 is
174	    /// taken over the closure so a J-cut's lead is kept, and the track delta
175	    /// is anchored on and applied to the CALLER's clips only — so a sound
176	    /// half dragged to a track of its own goes alone and its picture stays.
177	    pub fn move_clips(
178	        &self,
179	        clips: &[u32],
180	        delta: Ticks,
181	        track: Option<u32>,
182	    ) -> Result<Outcome, String> {
183	        let selection = self.selected_clips(clips)?;
184	        if selection.is_empty() {
185	            return Ok(Outcome::Identity);
186	        }
187	        let closure = self.selected_clips(&self.with_links(clips)?)?;
188	
189	        // Snapping the delta keeps a dragged clip on the grid: every start
190	        // is already on it, so a snapped delta lands on it too.
191	        let mut delta = self.snapped(delta);
192	        let earliest = closure.iter().map(|c| c.start).min().unwrap_or(0);
193	        if delta < -earliest {
194	            delta = -earliest;
195	        }
196	
197	        let index_delta = match track {
198	            None => 0i64,
199	            Some(destination) => {
200	                let destination_index = self.require_track_index(destination)? as i64;
201	                // The anchor is the FIRST clip of the selection in the
202	                // order the timeline draws — back-most track, then earliest
203	                // — and the whole selection moves by its offset, which is
204	                // what keeps a two-track selection two tracks apart.
205	                let mut keyed: Vec<(usize, Ticks, u32)> = Vec::new();
206	                for clip in &selection {
207	                    keyed.push((self.require_track_index(clip.track)?, clip.start, clip.id));
208	                }
209	                let anchor = keyed.iter().min().map(|k| k.0).unwrap_or(0) as i64;
210	                destination_index - anchor
211	            }
212	        };
213	
214	        let mut candidates: Vec<Clip> = Vec::new();
215	        for clip in &closure {
216	            let mut moved = (*clip).clone();
217	            moved.start = moved.start.saturating_add(delta).max(0);
218	            let named = selection.iter().any(|c| c.id == clip.id);
219	            if index_delta != 0 && named {
220	                let from = self.require_track_index(clip.track)? as i64;
221	                let to = from.saturating_add(index_delta);
222	                // A selection dragged off either end of the track list is a
223	                // refusal and not a clamp — clamping would silently stack
224	                // two clips on one track — and it says so in `move_track`'s
225	                // own words for the same mistake.
226	                let Some(destination) = usize::try_from(to)
227	                    .ok()
228	                    .and_then(|index| self.tracks.get(index))
229	                else {
230	                    return Ok(Outcome::Refused(format!(
231	                        "clip {} would land on track index {to}, which is out of range (0..{})",
232	                        clip.id,
233	                        self.tracks.len()
234	                    )));
235	                };
236	                moved.track = destination.id;
237	            }
238	            candidates.push(moved);
239	        }
240	
241	        self.commit_replacements(candidates)
242	    }
