291	    /// identity, which is the same answer a list of clips none of which
292	    /// straddles `at` gets there.
293	    pub fn split_under_playhead(&self, at: Ticks) -> Result<Outcome, String> {
294	        let at = self.snapped(at);
295	        let ids: Vec<u32> = self
296	            .clips
