334	impl Project {
335	    /// The insert edit: `media` lands whole at `at` on `track`, and
336	    /// everything at or after `at` moves later by its length (spec §6).
337	    ///
338	    /// The clip `at` falls strictly inside on THIS track is split first, so
339	    /// the insert lands between two clips rather than on top of one. Other
340	    /// tracks are not cut: `insert_time` shifts them whole, straddlers
341	    /// staying put, which is what keeps a music bed unbroken under an
342	    /// insert into the picture. The one exception is a cut clip's linked
343	    /// partner on an unlocked track, which `split_clips` cuts at the same
344	    /// `at` and pairs with it (spec §11 AU-92), so the pair stays in step
345	    /// through the inserted time.
346	    ///
347	    /// **A locked destination track refuses**, up front rather than by
348	    /// collision. `insert_time` will not shift a locked track, so the room
349	    /// an insert promises cannot be made there at all; leaving it to
350	    /// `add_clip` to notice would refuse only where the locked track
351	    /// happened to hold something at `at`, and quietly add a clip to a
352	    /// locked track everywhere else. `close_gap` refuses for the same
353	    /// reason.
354	    ///
355	    /// `Err` for an unknown track or media, or a media with no duration; a
356	    /// locked destination track refuses in [`locked_track`]'s words, and so
357	    /// does anything the inner `split`, `insert_time` or `add_clip` refused
358	    /// — this op answers in the words of whichever step declined.
359	    pub fn insert_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
360	        if self.require_track(track)?.locked {
361	            return Ok(Outcome::Refused(locked_track(
362	                track,
363	                "an insert cannot open room on it",
364	            )));
365	        }
366	        let found = self.require_media(media)?.clone();
367	        let at = self.snapped(at).max(0);
368	        let length = self.whole_media_length(&found)?;
369	
370	        let straddling: Vec<u32> = self
371	            .clips_on_track(track)
372	            .iter()
373	            .filter(|c| c.start < at && at < clip_end(c))
374	            .map(|c| c.id)
375	            .collect();
376	        let mut next = match self.split_clips(&straddling, at)? {
377	            Outcome::Applied(split) => split,
378	            // Nothing straddled the insertion point, which is the ordinary
379	            // case: carry on with the project as it is.
380	            Outcome::Identity => self.clone(),
381	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
382	        };
383	        match next.insert_time(at, length)? {
384	            Outcome::Applied(opened) => next = opened,
385	            Outcome::Identity => {}
386	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
387	        }
388	        // A composition answers in the words of whichever step declined, so
389	        // the overlap rule's sentence reaches the caller through here too.
390	        let placed = match next.add_clip(track, media, at)? {
391	            Outcome::Applied(placed) => placed,
392	            Outcome::Identity => return Ok(Outcome::Identity),
393	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
394	        };
395	        self.finish(placed)
396	    }
397	
398	    /// The overwrite edit: `media` lands whole at `at` on `track`, and
399	    /// whatever that track was playing across the span it needs is removed
400	    /// (spec §6). Nothing moves, and no other track is touched but for a
401	    /// cut clip's linked partner on an unlocked track: `split_clips` cuts it
402	    /// at the same bounds and pairs the pieces (spec §11 AU-92), and the
403	    /// partner's middle piece stays, its link settled away with the
404	    /// picture it was paired to.
405	    ///
406	    /// The span is cut at both bounds first, so everything that touched it
407	    /// afterwards lies entirely inside it and can be dropped whole; a clip
408	    /// that covered the whole span becomes a head and a tail with the new
409	    /// clip between them.
410	    ///
411	    /// The named track is cleared whether or not it is LOCKED — the caller
412	    /// named it, exactly as `ripple_delete` removes the clips it was given
413	    /// — while a lock still decides what may shift, which here is nothing.
414	    ///
415	    /// `Err` for an unknown track or media, or a media with no duration;
416	    /// whatever `add_clip` answered when the clip could not be placed after
417	    /// the span was cleared, in its own words.
418	    pub fn overwrite_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
419	        self.require_track(track)?;
420	        let found = self.require_media(media)?.clone();
421	        let at = self.snapped(at).max(0);
422	        let length = self.whole_media_length(&found)?;
423	        // Both bounds are already on the frame grid, so the span is too.
424	        let end = at.saturating_add(length);
425	
426	        let mut next = self.clone();
427	        for bound in [at, end] {
428	            let cut: Vec<u32> = next
429	                .clips_on_track(track)
430	                .iter()
431	                .filter(|c| c.start < bound && bound < clip_end(c))
432	                .map(|c| c.id)
433	                .collect();
434	            match next.split_clips(&cut, bound)? {
435	                Outcome::Applied(project) => next = project,
436	                Outcome::Identity => {}
437	                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
438	            }
439	        }
440	        let inside: Vec<u32> = next
441	            .clips_on_track(track)
442	            .iter()
443	            .filter(|c| c.start >= at && clip_end(c) <= end)
444	            .map(|c| c.id)
445	            .collect();
446	        next.clips.retain(|c| !inside.contains(&c.id));
447	
448	        let placed = match next.add_clip(track, media, at)? {
449	            Outcome::Applied(placed) => placed,
450	            Outcome::Identity => return Ok(Outcome::Identity),
451	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
452	        };
453	        self.finish(placed)
454	    }
455	}
