536	                // would break the merge contract. Merging the patch over
537	                // this preset (not under it) keeps an explicit
538	                // `"arrow_end": false` winning.
539	                let kind = patch
540	                    .get("kind")
541	                    .and_then(|value| serde_json::from_value(value.clone()).ok());
542	                let base = ShapeProps {
543	                    arrow_end: matches!(kind, Some(ShapeKind::Arrow)),
