553	        let scale = self.fit_scale(props.width, props.height);
554	        self.add_described_clip(
555	            track,
556	            at,
557	            duration,
558	            Described {
559	                source: Source::Shape,
560	                scale,
561	                text: None,
562	                shape: Some(props),
563	                graphic: None,
564	            },
