681	/// Whether the clip is an adjustment clip.
682	pub(crate) fn is_adjustment(clip: &Clip) -> bool {
683	    matches!(clip.source, Source::Adjustment)
684	}
685	
686	/// The one rule about an adjustment CLIP's video group: no neighbourhood
687	/// filter and no blend mode. An `Err`, as `check_blend`'s is, so `paste` and
688	/// `paste_attributes` meet it through `settle_video` and refuse the whole
689	/// paste. Any other clip passes.
690	pub(crate) fn check_adjustment_video(clip: &Clip, props: &VideoProps) -> Result<(), String> {
691	    if !is_adjustment(clip) {
692	        return Ok(());
693	    }
694	    for filter in &props.filters {
695	        let name = match filter.kind {
696	            FilterKind::Blur => "blur",
697	            FilterKind::Sharpen => "sharpen",
698	            FilterKind::Pixelate => "pixelate",
699	            FilterKind::Sepia | FilterKind::Noir | FilterKind::Vignette | FilterKind::Invert => {
700	                continue
701	            }
702	        };
703	        return Err(format!(
704	            "clip {} is an adjustment clip and cannot take the {name} filter",
705	            clip.id
706	        ));
707	    }
708	    if props.blend != BlendMode::Normal {
709	        return Err(format!(
710	            "clip {} is an adjustment clip and cannot take a blend mode",
711	            clip.id
712	        ));
713	    }
714	    Ok(())
715	}
