48	/// Default duration for a source with no source bound — text, shape, and an
49	/// image whose descriptor carries no duration. Five seconds is a common
50	/// title default and long enough to read.
51	pub(crate) const DEFAULT_CLIP_DURATION: Ticks = 5 * TIMESCALE;
52	
53	// ---- clip helpers --------------------------------------------------------
54	
55	pub(crate) fn clip_end(clip: &Clip) -> Ticks {
56	    clip.start.saturating_add(clip.duration)
57	}
