66	    /// How long a clip showing the WHOLE of `media` is — what `add_clip`
67	    /// gives one, and therefore how much room `insert_clip` opens and how
68	    /// much span `overwrite_clip` clears.
69	    ///
70	    /// **A timed media's length is THE bound at 1:1**, snapped DOWN
71	    /// (`source_window.rs`, spec §11): the nearest snap rounds UP past the
72	    /// end of the file, down-snapped `in + duration × speed ≤
73	    /// media.duration` holds and the rate is exactly 1. The price is a
74	    /// frame of the tail, and a media shorter than a frame, which is an
75	    /// `Err` naming the frame as one with no duration always has been.
76	    ///
77	    /// An image has no source bound and keeps the NEAREST snap of its
78	    /// descriptor's length or of the default — a constant is not on the
79	    /// grid of a rate that does not divide the timescale (at 30000/1001
80	    /// five seconds is 3 003 000 ticks, not 3 000 000), and the raw one
81	    /// made `insert_clip` open a hole wider than the clip it placed.
82	    pub(crate) fn whole_media_length(&self, media: &Media) -> Result<Ticks, String> {
83	        match media.kind {
84	            MediaKind::Lut => Err(crate::lut::lut_not_placeable(media.id)),
85	            MediaKind::Image if media.duration <= 0 => {
86	                Ok(self.snapped(DEFAULT_CLIP_DURATION).max(self.frame()))
87	            }
88	            MediaKind::Image => Ok(self.snapped(media.duration)),
89	            MediaKind::Video | MediaKind::Audio if media.duration <= 0 => Err(format!(
90	                "media {} has no duration ({} ticks)",
91	                media.id, media.duration
92	            )),
93	            MediaKind::Video | MediaKind::Audio => {
94	                // THE bound (`source_window.rs`) over the whole file from
95	                // tick 0 at 1:1; a literal 1.0 is always measurable.
96	                let duration = self
97	                    .longest_duration_on_grid_of(0, media, 0, 1.0)
98	                    .or_unbounded()
99	                    .unwrap_or(0);
100	                if duration <= 0 {
101	                    return Err(format!(
102	                        "media {} is shorter than a frame ({} ticks; a frame is {} ticks)",
103	                        media.id,
104	                        media.duration,
105	                        self.snapped_up(1)
106	                    ));
107	                }
108	                Ok(duration)
109	            }
110	        }
111	    }
112	
113	    // ---- adding clips ----------------------------------------------------
114	
115	    /// Places the whole of `media` as one clip at `at` on `track`, source
116	    /// in 0, with Fit scale when the canvas asks for it and the source
117	    /// exceeds it (spec §6).
118	    ///
119	    /// `video` is `null` for an audio-only file and `audio` is `null` for a
120	    /// file with no audio track, which is how the inspector knows which
121	    /// tabs to enable. Refuses when the placement breaks the overlap rule;
122	    /// `Err` for an unknown track or media, or a media with no usable
123	    /// duration.
124	    pub fn add_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
125	        self.require_track(track)?;
126	        let found = self.require_media(media)?.clone();
127	        // A drag can start left of zero; the timeline has no negative time.
128	        let at = self.snapped(at).max(0);
129	
130	        let duration = self.whole_media_length(&found)?;
131	        let source = match found.kind {
132	            MediaKind::Image => Source::Image { media },
133	            MediaKind::Video | MediaKind::Audio => Source::Media {
134	                media,
135	                r#in: 0,
136	                reversed: false,
137	            },
138	            MediaKind::Lut => return Err(crate::lut::lut_not_placeable(media)),
139	        };
140	
141	        let has_pixels = found.has_video || matches!(found.kind, MediaKind::Image);
142	        let video = has_pixels.then(|| VideoProps {
143	            scale: self.fit_scale(f64::from(found.width), f64::from(found.height)),
144	            ..VideoProps::default()
145	        });
146	        let audio = found.has_audio.then(AudioProps::default);
147	
148	        let mut next = self.clone();
149	        let clip = Clip {
150	            video,
151	            audio,
152	            ..Clip::placed(next.allocate_id(), track, at, duration, source)
153	        };
154	        self.commit_additions(next, vec![clip])
155	    }
