244	    /// The named clips, deduplicated, in the order given. `Err` on an
245	    /// unknown id — every multi-clip op names its clips explicitly, so a
246	    /// stale id is a caller bug, not a refusal.
247	    pub(crate) fn selected_clips(&self, clips: &[u32]) -> Result<Vec<&Clip>, String> {
248	        let mut out: Vec<&Clip> = Vec::new();
249	        for id in clips {
250	            let clip = self.require_clip(*id)?;
251	            if !out.iter().any(|c| c.id == clip.id) {
252	                out.push(clip);
253	            }
254	        }
255	        Ok(out)
256	    }
