258	    // ---- splitting, deleting, duplicating --------------------------------
259	
260	    /// Cuts each named clip at project time `at` (spec §6). A clip `at` is
261	    /// not strictly inside is skipped; when nothing can be cut the whole op
262	    /// is an identity. `Err` only for an unknown clip id.
263	    ///
264	    /// A linked partner is cut too, and the halves are paired (spec §11
265	    /// AU-92, `edit_link.rs`'s `pair_split_halves`).
266	    pub fn split_clips(&self, clips: &[u32], at: Ticks) -> Result<Outcome, String> {
267	        let at = self.snapped(at);
268	        let ids = self.with_links(clips)?;
269	        let mut next = self.clone();
270	        let mut halves: Vec<(u32, u32)> = Vec::new();
271	        for id in ids {
272	            // `split_clip` allocates the second half's id first.
273	            let second = next.next_id;
274	            if split_clip(&mut next, id, at) {
275	                halves.push((id, second));
276	            }
277	        }
278	        if halves.is_empty() {
279	            return Ok(Outcome::Identity);
280	        }
281	        pair_split_halves(&mut next, &halves);
282	        self.finish(next)
283	    }
